<span class="sf-size-row">
    <span class="sf-size-identity"><span class="sf-size-token">{{ $size }}</span><span><span class="sf-row-caption">SKU</span><span class="sf-size-sku">{{ $sku }}</span></span></span>
    <span class="sf-size-prices"><span class="sf-row-caption">Saved selling price</span><span data-price-currency="PKR">{{ $pkr > 0 ? \App\Services\Pricing::format($pkr, 'PKR') : 'PKR - not set' }}</span><span data-price-currency="USD">{{ $usd > 0 ? \App\Services\Pricing::format($usd, 'USD') : 'USD - not set' }}</span></span>
    <span class="sf-size-stock"><span class="sf-row-caption">Saved stock</span><strong>{{ $available }} available</strong><span>On hand {{ $onHand ?? 'not entered' }} &middot; Reserved {{ $reserved }}</span></span>
    <span class="sf-size-state"><span class="sf-status-badge {{ $ready ? 'is-ready' : 'needs-review' }}">{{ $status }}</span><span class="sf-row-caption">{{ match ($status) { 'Inactive' => 'Edit size to reactivate if this SKU is still offered.', 'Stock has never been entered' => 'Fix / edit stock: enter the opening balance.', 'Sold out' => 'Fix / edit stock: receive stock when it arrives.', 'All units reserved' => 'Stock belongs to open orders. Receive more units or review those orders.', 'Needs PKR price' => 'Fix / edit price: set the Pakistan selling price.', 'Hidden by publication' => 'Check product and category visibility.', default => 'Ready. Use the row actions to change saved price or stock.' } }}</span></span>
</span>
